Inductive List = elt Int | cons {Int, List};

is_sorted = let aux = (fix (
    \f: Int -> List -> Bool. \pre: Int. \xs: List. 
    match xs with
      elt x -> <= pre x
    | cons {h, t} -> and (<= pre h) (f h t)
    end
)) in 
        \xs: List. 
        match xs with
          elt x -> true
        | cons {h, t} -> aux h t
        end
;

min = \a: Int. \b: Int. 
    if (> a b) then b
    else a;

spec = fix (
    \f: List -> Int. \xs: List. 
    match xs with
      elt w -> w
    | cons {h, t} -> min h (f t)
    end
);

target = fix (
    \f: List -> Compress List. \xs: List. 
    match xs with
      elt w -> 
        align (label xs ) 
    | cons {h, t} -> 
        let tmp1 = (f t) in 
            align (label (cons {h, unlabel tmp1 }) ) 
    end
);

main = \xs: List. 
    if (is_sorted xs) then let tmp2 = (target xs) in 
        align (spec (unlabel tmp2 )) 
    else 0;


main (cons {(-3), (cons {(-1), (cons {(3), (cons {(1), (cons {(3), (elt 0)})})})})});
main (cons {(-2), (cons {(4), (cons {(4), (cons {(-4), (cons {(4), (cons {(5), (cons {(-2), (cons {(-1), (cons {(2), (elt 1)})})})})})})})})});
main (cons {(4), (cons {(3), (cons {(-3), (cons {(3), (cons {(-4), (elt 1)})})})})});
main (cons {(4), (cons {(1), (elt 2)})});
main (cons {(-4), (cons {(-5), (cons {(0), (cons {(2), (elt -5)})})})});
main (cons {(5), (cons {(-4), (cons {(1), (elt 1)})})});
main (elt 1);
main (cons {(-1), (elt 2)});
main (elt 5);
main (cons {(0), (cons {(-3), (cons {(1), (cons {(1), (cons {(2), (elt 2)})})})})});
