Inductive List = nil Unit | cons {Int, List};

spec = fix (
    \f: List -> Int. \xs: List. 
    match xs with
      nil _ -> 0
    | cons {h, t} -> + h (f t)
    end
);

snoc = fix (
    \f: List -> Int -> List. \xs: List. \w: Int. 
    match xs with
      nil _ -> cons {w, nil unit}
    | cons {h, t} -> cons {h, f t w}
    end
);

repr = fix (
    \f: Compress List -> List -> Compress List. \pre: Compress List. \xs: List. 
    match xs with
      nil _ -> pre
    | cons {h, t} -> f (align (label (snoc (unlabel pre ) ) ) ) ) t
    end
) (let tmp1 = (snoc (unlabel tmp1 ) ) ) ) ) t
    end
) (let tmp2 = (snoc (unlabel tmp2 ) ) ) ) t
    end
);

main = \xs: List. 
    let tmp3 = (repr xs) in 
        align (spec (unlabel tmp3 )) ;


