Inductive List = elt Int | cons {Int, List};

Inductive IDList = ielt Int | icons {Int, Int, IDList};

is_sorted = let aux = (fix (
    \f: Int -> IDList -> Bool. \pre: Int. \xs: IDList. 
    match xs with
      ielt x -> > pre x
    | icons {h, _, t} -> and (> pre h) (f h t)
    end
)) in 
        \xs: IDList. 
        match xs with
          ielt x -> true
        | icons {h, _, t} -> aux h t
        end
;

len = fix (
    \f: IDList -> Int. \xs: IDList. 
    match xs with
      ielt _ -> 1
    | icons {_, _, t} -> + 1 (f t)
    end
);

len_raw = fix (
    \f: List -> Int. \xs: List. 
    match xs with
      elt _ -> 1
    | cons {_, t} -> + 1 (f t)
    end
);

is_indexed = fix (
    \f: IDList -> Bool. \xs: IDList. 
    match xs with
      ielt _ -> true
    | icons {_, id, t} -> and (== id (len xs)) (f t)
    end
);

add_index = fix (
    \f: List -> IDList. \xs: List. 
    match xs with
      elt a -> ielt a
    | cons {h, t} -> icons {h, len_raw xs, f t}
    end
);

drop_index = fix (
    \f: IDList -> List. \xs: IDList. 
    match xs with
      ielt a -> elt a
    | icons {h, _, t} -> cons {h, f t}
    end
);

w = 100;

spec = fix (
    \f: List -> Int. \xs: List. 
    match xs with
      elt x -> if (< x w) then 1
        else 0
    | cons {h, t} -> + (f t) (if (< h w) then 1
        else -1)
    end
);

target = fix (
    \f: IDList -> Compress IDList. \xs: IDList. 
    match xs with
      ielt x -> 
        align (label xs ) 
    | icons {h, idx, t} -> if (< h w) then let tmp1 = (f t) in 
            align (label (icons {h, idx, unlabel tmp1 }) ) 
        else let tmp2 = (f t) in 
            align (label (icons {h, idx, unlabel tmp2 }) ) 
    end
);

main = \xs: IDList. 
    if (is_indexed xs) then let tmp3 = (target xs) in 
        align (spec (drop_index (unlabel tmp3 ))) 
    else 0;


