Inductive List = cons {Int, List} | nil Unit;

single_pass = \v: List -> Int. 
    let run = (fix (
    \f: List -> Compress List. \xs: List. 
    match xs with
      nil _ -> 
        align (label xs ) 
    | cons {h, t} -> 
        let tmp1 = (f t) in 
            align (label (cons {h, unlabel tmp1 }) ) 
    end
)) in 
        \xs: List. 
        let tmp2 = (run xs) in 
            align (v (unlabel tmp2 )) ;

mps = fix (
    \f: List -> Int. \xs: List. 
    match xs with
      nil _ -> 0
    | cons {h, t} -> 
        let idx = (mps t) in 
            let tmp3 = (f t) in 
                align (min (max idx (max tmp3 (unlabel tmp3 )) ) (f t)
    end
) xs).1;

main = single_pass mps;


