    else b;

spec = fix (
    \f: List -> {Int, Int}. \xs: List. 
    match xs with
      nil _ -> {0, 0}
    | cons {h, t} -> 
        let res = (f t) in 
            {if (> h res.2) then max (+ res.1 h) 0
            else res.1, + res.2 1}
    end
);

target = fix (
    \f: IDList -> Compress IDList. \xs: IDList. 
    match xs with
      inil _ -> 
        let tmp1 = (inil unit) in 
