    | _ -> 
        let sp = (split xs) in 
            let tmp1 = (f sp.1) in 
                let tmp2 = (f sp.2) in 
                    align (label (concat (unlabel tmp1 ) (unlabel tmp2 )) ) 
    end
)) in 
